import React from 'react';
import { ArrowRight, TrendingUp, ShieldCheck } from 'lucide-react';
import { motion } from 'framer-motion';

const Hero: React.FC = () => {
  const scrollToContact = () => {
    document.getElementById('contact')?.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <section className="relative min-h-screen flex items-center justify-center overflow-hidden pt-20">
      {/* Background Elements */}
      <div className="absolute inset-0 bg-brand-dark z-0 overflow-hidden">
        {/* Top Center Blob - Primary Color */}
        <motion.div
          animate={{
            x: ["-50%", "-45%", "-55%", "-50%"],
            y: [0, -20, 20, 0],
            scale: [1, 1.1, 0.95, 1],
          }}
          transition={{
            duration: 18,
            repeat: Infinity,
            ease: "easeInOut",
          }}
          className="absolute top-[-10%] left-1/2 w-[800px] h-[600px] bg-brand-primary/20 blur-[120px] rounded-full opacity-40 pointer-events-none"
        />

        {/* Bottom Right Blob - Accent Color */}
        <motion.div
          animate={{
            x: [0, -30, 30, 0],
            y: [0, -40, 20, 0],
            scale: [1, 1.2, 0.9, 1],
          }}
          transition={{
            duration: 20,
            repeat: Infinity,
            ease: "easeInOut",
          }}
          className="absolute bottom-[-10%] right-[-10%] w-[600px] h-[500px] bg-brand-accent/15 blur-[100px] rounded-full opacity-30 pointer-events-none"
        />

        {/* Middle Left Blob - Secondary/Blue Color (Added for balance) */}
        <motion.div
          animate={{
            x: [0, 40, -40, 0],
            y: [0, 30, -30, 0],
            scale: [1, 1.1, 1],
          }}
          transition={{
            duration: 25,
            repeat: Infinity,
            ease: "easeInOut",
          }}
          className="absolute top-[30%] left-[-10%] w-[500px] h-[500px] bg-blue-600/10 blur-[90px] rounded-full opacity-20 pointer-events-none"
        />
      </div>

      <div className="container mx-auto px-6 relative z-10 text-center">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-brand-primary/10 border border-brand-primary/20 text-brand-accent mb-8"
        >
          <span className="relative flex h-3 w-3">
            <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-brand-accent opacity-75"></span>
            <span className="relative inline-flex rounded-full h-3 w-3 bg-brand-accent"></span>
          </span>
          <span className="text-sm font-medium tracking-wide">Nur für SaaS & Finanzdienstleister</span>
        </motion.div>

        <motion.h1
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.1 }}
          className="text-4xl md:text-6xl lg:text-7xl font-extrabold text-white leading-tight mb-6"
        >
          Planbare Neukunden. <br />
          <span className="gradient-text">Ohne Fixkosten.</span>
        </motion.h1>

        <motion.p
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.2 }}
          className="text-lg md:text-xl text-slate-300 max-w-2xl mx-auto mb-10 leading-relaxed"
        >
          Ich bin dein Growth-Partner, nicht nur eine Agentur. Ich werde nur bezahlt,
          wenn dein Unternehmen wächst. Kein Erfolg = Keine Kosten.
        </motion.p>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.3 }}
          className="flex flex-col sm:flex-row items-center justify-center gap-4"
        >
          <button
            onClick={scrollToContact}
            className="group relative px-8 py-4 bg-brand-primary hover:bg-brand-accent text-white rounded-lg font-bold text-lg transition-all shadow-lg shadow-brand-primary/25 hover:shadow-brand-primary/40 flex items-center gap-2"
          >
            Erstgespräch buchen
            <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
          </button>

          <div className="flex items-center gap-6 px-6 py-4 text-slate-400 text-sm font-medium">
            <div className="flex items-center gap-2">
              <ShieldCheck className="w-5 h-5 text-brand-success" />
              <span>0% Risiko</span>
            </div>
            <div className="flex items-center gap-2">
              <TrendingUp className="w-5 h-5 text-brand-success" />
              <span>100% Performance</span>
            </div>
          </div>
        </motion.div>
      </div>
    </section>
  );
};

export default Hero;
